{
  "name": "nested-comments",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "start": "node server/index.js",
    "build": "cd client && npm run build",
    "dev": "concurrently \"node server/index.js\" \"cd client && npm run dev\""
  },
  "dependencies": {
    "express": "^4.18.2",
    "uuid": "^9.0.0"
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    proxy: {
      '/api': {
        target: 'http://localhost:5732',
        changeOrigin: true,
      },
    },
  },
  build: {
    outDir: 'dist',
  },
});

const express = require('express');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = 5732;

// In-memory comments store
const comments = [
  {
    id: '1',
    text: 'Welcome to the nested comments!',
    parentId: null,
  },
  {
    id: '2',
    text: 'This is a reply to the first comment.',
    parentId: '1',
  },
  {
    id: '3',
    text: 'Another top-level comment.',
    parentId: null,
  },
];

app.use(express.json());

// GET /api/comments - return all comments
app.get('/api/comments', (_req, res) => {
  res.status(200).json(comments);
});

// POST /api/comments - add a new comment with 1000ms artificial delay
app.post('/api/comments', (req, res) => {
  const { text, parentId } = req.body;

  if (!text || typeof text !== 'string' || text.trim().length === 0) {
    return res.status(400).json({ error: 'Text is required' });
  }

  const newComment = {
    id: uuidv4(),
    text: text.trim(),
    parentId: parentId || null,
  };

  // Artificial 1000ms delay to make optimistic updates observable
  setTimeout(() => {
    comments.push(newComment);
    res.status(201).json(newComment);
  }, 1000);
});

// Serve the built React app in production
const clientDistPath = path.join(__dirname, '..', 'client', 'dist');
app.use(express.static(clientDistPath));
app.get('*', (_req, res) => {
  res.sendFile(path.join(clientDistPath, 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import App from './App';
import './index.css';

const queryClient = new QueryClient();

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <App />
    </QueryClientProvider>
  </React.StrictMode>
);

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
    Ubuntu, Cantarell, sans-serif;
  background: #f5f5f5;
  color: #333;
  line-height: 1.6;
}

.app {
  max-width: 700px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.app h1 {
  margin-bottom: 1.5rem;
  font-size: 1.75rem;
  color: #1a1a1a;
}

/* Comment Form */
.comment-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.comment-form input {
  flex: 1;
  padding: 0.65rem 0.85rem;
  border: 1px solid #ccc;
  border-radius: 6px;
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.15s;
}

.comment-form input:focus {
  border-color: #4f46e5;
  box-shadow: 0 0 0 2px rgba(79, 70, 229, 0.15);
}

.comment-form button {
  padding: 0.65rem 1.25rem;
  background: #4f46e5;
  color: #fff;
  border: none;
  border-radius: 6px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s;
}

.comment-form button:hover {
  background: #4338ca;
}

.comment-form button:disabled {
  background: #9ca3af;
  cursor: not-allowed;
}

/* Comment List */
.comment-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Comment Item */
.comment-item {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 0.85rem 1rem;
  margin-bottom: 0.5rem;
}

.comment-item.optimistic {
  opacity: 0.55;
  border-style: dashed;
  border-color: #4f46e5;
  background: #eef2ff;
}

.comment-text {
  font-size: 0.95rem;
}

/* Nested children */
.comment-children {
  margin-left: 1.5rem;
  padding-left: 1rem;
  border-left: 2px solid #e5e7eb;
}

/* Loading / Error / Empty states */
.status-message {
  text-align: center;
  padding: 2rem;
  color: #6b7280;
  font-size: 0.95rem;
}

.status-message.error {
  color: #dc2626;
}

const API_BASE = '/api';

export async function fetchComments() {
  const res = await fetch(`${API_BASE}/comments`);
  if (!res.ok) {
    throw new Error('Failed to fetch comments');
  }
  return res.json();
}

export async function postComment({ text, parentId }) {
  const res = await fetch(`${API_BASE}/comments`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text, parentId: parentId || null }),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || 'Failed to post comment');
  }
  return res.json();
}

import React from 'react';

function buildTree(comments) {
  const map = {};
  const roots = [];

  for (const c of comments) {
    map[c.id] = { ...c, children: [] };
  }

  for (const c of comments) {
    if (c.parentId && map[c.parentId]) {
      map[c.parentId].children.push(map[c.id]);
    } else {
      roots.push(map[c.id]);
    }
  }

  return roots;
}

function CommentItem({ comment }) {
  return (
    <div className={`comment-item${comment._optimistic ? ' optimistic' : ''}`}>
      <div className="comment-text">{comment.text}</div>
      {comment.children && comment.children.length > 0 && (
        <div className="comment-children">
          {comment.children.map((child) => (
            <CommentItem key={child.id} comment={child} />
          ))}
        </div>
      )}
    </div>
  );
}

export default function CommentList({ comments, isLoading, isError, error }) {
  if (isLoading) {
    return <div className="status-message">Loading comments...</div>;
  }

  if (isError) {
    return (
      <div className="status-message error">
        Error: {error?.message || 'Something went wrong'}
      </div>
    );
  }

  const tree = buildTree(comments || []);

  if (tree.length === 0) {
    return <div className="status-message">No comments yet. Be the first!</div>;
  }

  return (
    <div className="comment-list">
      {tree.map((comment) => (
        <CommentItem key={comment.id} comment={comment} />
      ))}
    </div>
  );
}

import React, { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postComment } from './api';

export default function CommentForm() {
  const [text, setText] = useState('');
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: postComment,
    onMutate: async (newComment) => {
      // Cancel any outgoing refetches so they don't overwrite our optimistic update
      await queryClient.cancelQueries({ queryKey: ['comments'] });

      // Snapshot the previous value for rollback
      const previousComments = queryClient.getQueryData(['comments']);

      // Optimistically update the cache
      queryClient.setQueryData(['comments'], (old) => {
        const optimisticComment = {
          id: 'optimistic-' + Date.now(),
          text: newComment.text,
          parentId: newComment.parentId || null,
          _optimistic: true,
        };
        return [...(old || []), optimisticComment];
      });

      // Return the snapshot for onError rollback
      return { previousComments };
    },
    onError: (_err, _newComment, context) => {
      // Roll back to the previous value on error
      if (context?.previousComments) {
        queryClient.setQueryData(['comments'], context.previousComments);
      }
    },
    onSettled: () => {
      // Always refetch to ensure the UI is in sync with the server
      queryClient.invalidateQueries({ queryKey: ['comments'] });
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const trimmed = text.trim();
    if (!trimmed) return;

    mutation.mutate({ text: trimmed, parentId: null });
    setText('');
  };

  return (
    <form className="comment-form" onSubmit={handleSubmit}>
      <input
        type="text"
        name="commentText"
        id="commentText"
        placeholder="Write a comment..."
        value={text}
        onChange={(e) => setText(e.target.value)}
        disabled={mutation.isPending}
      />
      <button type="submit" id="submitComment" disabled={mutation.isPending || !text.trim()}>
        Submit
      </button>
    </form>
  );
}

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { fetchComments } from './api';
import CommentForm from './CommentForm';
import CommentList from './CommentList';

export default function App() {
  const { data: comments, isLoading, isError, error } = useQuery({
    queryKey: ['comments'],
    queryFn: fetchComments,
  });

  return (
    <div className="app">
      <h1>Nested Comments</h1>
      <CommentForm />
      <CommentList
        comments={comments}
        isLoading={isLoading}
        isError={isError}
        error={error}
      />
    </div>
  );
}

